package wshandler

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"sync"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	ReadBufferSize:  1024,
	WriteBufferSize: 1024,
	CheckOrigin:     checkOrigin,
}

var sessionStore = &sync.Map{}

// secretKey is loaded from the environment at startup instead of being
// hard-coded in source (avoids CWE-798).
var secretKey = loadSecretKey()

func loadSecretKey() []byte {
	k := os.Getenv("WS_HMAC_SECRET")
	if k == "" {
		log.Fatal("WS_HMAC_SECRET environment variable must be set")
	}
	return []byte(k)
}

type Session struct {
	UserID    string
	ConnID    string
	Verified  bool
	UploadBuf []byte
	mu        sync.Mutex
}

type MessageHeader struct {
	MsgType  uint8
	Length   uint32
	Checksum [32]byte
}

const (
	MsgAuth     uint8 = 0x01
	MsgUpload   uint8 = 0x02
	MsgDeserialize uint8 = 0x03
)

func checkOrigin(r *http.Request) bool {
	origin := r.Header.Get("Origin")
	if origin == "" {
		return false
	}
	allowed := []string{"https://app.example.com", "https://admin.example.com"}
	for _, a := range allowed {
		if origin == a {
			return true
		}
	}
	return false
}

func verifyToken(token string, connID string) bool {
	if len(token) < 64 {
		return false
	}
	mac := hmac.New(sha256.New, secretKey)
	mac.Write([]byte(connID))
	expected := mac.Sum(nil)
	provided, err := hex.DecodeString(token[:64])
	if err != nil {
		return false
	}
	return hmac.Equal(expected, provided)
}

func validateChecksum(data []byte, expected [32]byte) bool {
	actual := sha256.Sum256(data)
	return hmac.Equal(actual[:], expected[:])
}

func parseHeader(raw []byte) (*MessageHeader, error) {
	if len(raw) < 37 {
		return nil, fmt.Errorf("header too short")
	}
	h := &MessageHeader{
		MsgType: raw[0],
		Length:  binary.BigEndian.Uint32(raw[1:5]),
	}
	copy(h.Checksum[:], raw[5:37])
	return h, nil
}

func processUpload(session *Session, data []byte) error {
	if len(data) > 1<<20 {
		return fmt.Errorf("upload too large")
	}
	session.mu.Lock()
	defer session.mu.Unlock()
	session.UploadBuf = append(session.UploadBuf, data...)
	return nil
}

func deserializePayload(session *Session) (interface{}, error) {
	session.mu.Lock()
	defer session.mu.Unlock()
	if len(session.UploadBuf) == 0 {
		return nil, fmt.Errorf("no data to deserialize")
	}
	// Custom deserialization: first 4 bytes = type tag
	if len(session.UploadBuf) < 4 {
		return nil, fmt.Errorf("invalid payload")
	}
	typeTag := binary.BigEndian.Uint32(session.UploadBuf[:4])
	payload := session.UploadBuf[4:]
	switch typeTag {
	case 0x01:
		return string(payload), nil
	case 0x02:
		return payload, nil
	default:
		return nil, fmt.Errorf("unknown type tag: %d", typeTag)
	}
}

func HandleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	defer conn.Close()

	connID := r.Header.Get("X-Connection-ID")
	if connID == "" {
		conn.WriteMessage(websocket.CloseMessage, []byte("missing connection id"))
		return
	}

	session := &Session{ConnID: connID}
	sessionStore.Store(connID, session)
	defer sessionStore.Delete(connID)

	for {
		_, message, err := conn.ReadMessage()
		if err != nil {
			if err != io.EOF {
				fmt.Printf("read error: %v\n", err)
			}
			break
		}

		header, err := parseHeader(message)
		if err != nil {
			conn.WriteMessage(websocket.TextMessage, []byte("invalid header"))
			continue
		}

		payload := message[37:]
		if uint32(len(payload)) != header.Length {
			conn.WriteMessage(websocket.TextMessage, []byte("length mismatch"))
			continue
		}

		switch header.MsgType {
		case MsgAuth:
			token := string(payload)
			if verifyToken(token, connID) {
				session.Verified = true
				session.UserID = token[64:]
				conn.WriteMessage(websocket.TextMessage, []byte("authenticated"))
			} else {
				conn.WriteMessage(websocket.TextMessage, []byte("auth failed"))
			}

		case MsgUpload:
			if !session.Verified {
				conn.WriteMessage(websocket.TextMessage, []byte("not authenticated"))
				continue
			}
			if !validateChecksum(payload, header.Checksum) {
				conn.WriteMessage(websocket.TextMessage, []byte("checksum failed"))
				continue
			}
			if err := processUpload(session, payload); err != nil {
				conn.WriteMessage(websocket.TextMessage, []byte(err.Error()))
			}

		case MsgDeserialize:
			// Verify session is authenticated before deserialization
			if !session.Verified {
				conn.WriteMessage(websocket.TextMessage, []byte("not authenticated"))
				continue
			}
			result, err := deserializePayload(session)
			if err != nil {
				conn.WriteMessage(websocket.TextMessage, []byte(err.Error()))
			} else {
				conn.WriteMessage(websocket.TextMessage, []byte(fmt.Sprintf("%v", result)))
			}

		default:
			conn.WriteMessage(websocket.TextMessage, []byte("unknown message type"))
		}
	}
}
